function renderMarkdown(container,text){container.replaceChildren();const inline=(parent,value)=>{const parts=value.split(/(\*\*[^*]+\*\*|`[^`]+`)/g);for(const part of parts){if(part.startsWith('**')&&part.endsWith('**')){const strong=document.createElement('strong');strong.textContent=part.slice(2,-2);parent.append(strong);}else if(part.startsWith('`')&&part.endsWith('`')){const code=document.createElement('code');code.textContent=part.slice(1,-1);parent.append(code);}else parent.append(document.createTextNode(part));}};let list=null,code=null;for(const line of text.split('\n')){if(line.startsWith('```')){if(code){code=null;}else{code=document.createElement('pre');container.append(code);}list=null;continue;}if(code){code.textContent+=line+'\n';continue;}if(!line.trim()){list=null;continue;}const bullet=line.match(/^\s*(?:[-*•]|\d+[.)、])\s+(.+)/);if(bullet){if(!list){list=document.createElement('ul');container.append(list);}const li=document.createElement('li');inline(li,bullet[1]);list.append(li);continue;}list=null;const heading=line.match(/^#{1,4}\s+(.+)/);const p=document.createElement(heading?'h3':'p');inline(p,heading?heading[1]:line);container.append(p);}}
function addMessage(role,text,options={}){const box=document.createElement('article');box.className='message '+role;box.dataset.text=text;const label=document.createElement('small');label.textContent=role==='user'?'你':'Health Care Agent';const body=document.createElement('div');body.className='message-body';if(role==='user')body.textContent=text;else renderMarkdown(body,text);box.append(label,body);if(options.image){const img=document.createElement('img');img.src=options.image;img.alt='本次发送的照片';img.style.cssText='max-width:180px;max-height:180px;border-radius:12px;margin-top:9px';box.append(img);}if(role==='assistant'&&!options.streaming)messageActions(box,text);if(options.streaming)box.classList.add('streaming');$('messages').append(box);return box;}
function messageActions(box,text){const actions=document.createElement('div');actions.className='message-actions';const copy=document.createElement('button');copy.textContent='复制';copy.onclick=async()=>{try{await navigator.clipboard.writeText(text);toast('已复制');}catch{toast('复制未成功，可以长按文字复制。');}};const remember=document.createElement('button');remember.textContent='存入记忆';remember.onclick=async()=>{try{const current=await request('profile');const next=(current.text||'')+'\n我选择保留的一段对话（不代表已验证的事实）：'+text;if(next.length>12000){toast('记忆快满了，请到生活页整理后再保存。');return;}await request('profile','POST',{text:next});$('profile').value=next;toast('已存入个人背景，以后聊天会参考。');}catch(e){toast(e.message);}};actions.append(copy,remember);box.append(actions);}
function scrollChat(force=false){const el=$('chat-scroll');if(force||autoFollow){el.scrollTop=el.scrollHeight;$('jump-latest').hidden=true;autoFollow=true;}else $('jump-latest').hidden=false;}
function renderFollowups(){const box=$('followups');box.replaceChildren();if(!messages.length)return;for(const [label,text] of [['继续聊这个','你刚才说的这一点，我想再聊聊。'],['说得更直白些','能把刚才那段话说得更直白一点吗？'],['今天怎么做','那如果只选一件我今天能做的事，你会建议什么？']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>promptChat(text);box.append(b);}}
function renderThreadList(){const box=$('thread-list');box.replaceChildren();for(const t of threadItems){const row=document.createElement('div');row.className='thread'+(t.id===activeThread?' active':'');const pick=document.createElement('button');pick.textContent=t.title;const date=document.createElement('small');date.textContent=new Date(t.updated_at).toLocaleDateString('zh-CN');pick.append(date);pick.onclick=async()=>{if(chatAbort){toast('请先等这一条回复完成，或停止生成。');return;}activeThread=t.id;try{localStorage.setItem('zhiji-active-thread',activeThread);}catch{}closeDialog('history-dialog');await loadChat();scrollChat(true);};const remove=document.createElement('button');remove.className='thread-delete';remove.textContent='×';remove.setAttribute('aria-label','删除此对话');remove.onclick=async()=>{if(chatAbort){toast('请先停止生成。');return;}if(!confirm('删除“'+t.title+'”这段对话？其他对话和生活记录会保留。'))return;try{await request('chat','DELETE',{threadId:t.id});if(activeThread===t.id)activeThread='legacy';await loadChat();}catch(e){toast(e.message);}};row.append(pick,remove);box.append(row);}if(!threadItems.length){const p=document.createElement('p');p.className='empty';p.textContent='从第一句话，开始认识彼此。';box.append(p);}}
async function loadChat(){let d;try{d=await request('chat?threadId='+encodeURIComponent(activeThread));}catch(e){if(activeThread!=='legacy'){activeThread='legacy';d=await request('chat?threadId=legacy');}else throw e;}messages=d.messages;threadItems=d.threads;olderCursor=d.cursor;chatHasMore=d.hasMore;$('older-messages').hidden=!d.hasMore;$('messages').replaceChildren();for(const m of messages)addMessage(m.role,m.text+(m.hasImage?'\n[这条消息曾附照片，照片未保留]':''));$('chat-welcome').hidden=messages.length>0;const status=d.ready?'已连接 · 可以接着聊':'暂未连接模型，请查看设置';set('model-status',status);set('model-config-status',d.ready?'模型已连接 · '+d.model:'模型尚未配置');set('chat-subtitle',threadItems.find(t=>t.id===activeThread)?.title||'懂你的数据，也愿意听你说。');try{localStorage.setItem('zhiji-active-thread',activeThread);}catch{}renderThreadList();renderFollowups();scrollChat(true);}
async function newChat(){if(chatAbort){toast('请先等回复完成，或停止生成。');return;}try{const d=await request('chat','POST',{action:'new'});activeThread=d.thread.id;await loadChat();view('chat');closeDialog('history-dialog');$('question').value='';resizeComposer();toast('新的对话开始了。之前的聊天还在历史里。');}catch(e){toast(e.message);}}
async function olderMessages(){if(!olderCursor||!chatHasMore)return;const scroll=$('chat-scroll'),oldHeight=scroll.scrollHeight;try{const d=await request('chat?threadId='+encodeURIComponent(activeThread)+'&beforeTime='+encodeURIComponent(olderCursor.time)+'&beforeId='+encodeURIComponent(olderCursor.id));messages=[...d.messages,...messages];$('messages').replaceChildren();for(const m of messages)addMessage(m.role,m.text+(m.hasImage?'\n[这条消息曾附照片，照片未保留]':''));olderCursor=d.cursor;chatHasMore=d.hasMore;$('older-messages').hidden=!d.hasMore;scroll.scrollTop=scroll.scrollHeight-oldHeight;}catch(e){toast(e.message);}}
async function consumeChat(response,onEvent){const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';try{while(true){const {value,done}=await reader.read();buffer+=done?decoder.decode():decoder.decode(value,{stream:true});buffer=buffer.replace(/\r\n/g,'\n');let boundary;while((boundary=buffer.indexOf('\n\n'))>=0){const chunk=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);const data=chunk.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5).trimStart()).join('\n');if(data)onEvent(JSON.parse(data));}if(done)break;}}finally{reader.releaseLock();}}
function resizeComposer(){$('question').style.height='auto';$('question').style.height=Math.min(120,Math.max(33,$('question').scrollHeight))+'px';}
async function sendChat(){if(chatAbort)return;const question=$('question').value.trim()||(image?'帮我看看这顿饭大概有多少热量，先给个范围就好。':'');if(!question)return;const sentImage=image;const controller=new AbortController();chatAbort=controller;lastSend={question,image:sentImage};autoFollow=true;$('send').hidden=true;$('stop-chat').hidden=false;$('chat-welcome').hidden=true;$('followups').replaceChildren();$('question').value='';resizeComposer();removeImage();set('chat-status','正在看看你的数据，也听听前面聊了什么……');let userBox,assistantBox,answer='',finished=false;try{if(activeThread==='legacy'&&!messages.length){const d=await request('chat','POST',{action:'new'});activeThread=d.thread.id;try{localStorage.setItem('zhiji-active-thread',activeThread);}catch{}}userBox=addMessage('user',question,{image:sentImage});assistantBox=addMessage('assistant','',{streaming:true});const body=assistantBox.querySelector('.message-body');const typing=document.createElement('div');typing.className='typing';for(let i=0;i<3;i++)typing.append(document.createElement('i'));body.append(typing);scrollChat(true);const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:question,image:sentImage,reportPeriod:reportData?reportPeriod:undefined,threadId:activeThread,days:Number($('range').value),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,style:$('chat-style').value,stream:true}),signal:controller.signal});if(!response.ok){const error=await response.json().catch(()=>({}));throw new Error(error.error||'这次没连上，请再试一次。');}await consumeChat(response,event=>{if(event.type==='delta'){answer+=event.text;renderMarkdown(body,answer);set('chat-status','');scrollChat();}else if(event.type==='done'){finished=true;set('chat-status','对话已保存，可以继续说。');const meta=document.createElement('div');meta.className='message-meta';meta.textContent='参考近期身体数据与 '+event.context.journalCount+' 条生活记录';assistantBox.append(meta);}else if(event.type==='error')throw new Error(event.error);});if(!finished)throw new Error('回复中断了，点重试继续。');assistantBox.classList.remove('streaming');messageActions(assistantBox,answer);messages.push({role:'user',text:question},{role:'assistant',text:answer});renderFollowups();const latest=await request('chat?threadId='+encodeURIComponent(activeThread));threadItems=latest.threads;renderThreadList();set('chat-subtitle',threadItems.find(t=>t.id===activeThread)?.title||'和Health Care Agent接着聊');}catch(e){assistantBox?.classList.remove('streaming');if(!answer)assistantBox?.remove();if(!finished){set('chat-status',e.name==='AbortError'?'已停止。未完成的回复没有保存。':e.message);const retry=document.createElement('button');retry.className='text-button';retry.textContent='↻ 重试这一条';retry.onclick=()=>{userBox?.remove();assistantBox?.remove();$('question').value=question;image=sentImage;if(image){$('attached-image').src=image;$('image-preview').hidden=false;}resizeComposer();sendChat();};$('followups').replaceChildren(retry);}}finally{chatAbort=null;$('send').hidden=false;$('stop-chat').hidden=true;scrollChat();}}
$('chat-form').onsubmit=e=>{e.preventDefault();sendChat();};$('question').oninput=resizeComposer;$('question').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();sendChat();}};$('stop-chat').onclick=()=>chatAbort?.abort();$('new-chat').onclick=newChat;$('history-new').onclick=newChat;$('open-history').onclick=()=>{renderThreadList();openDialog('history-dialog');};$('older-messages').onclick=olderMessages;$('chat-style').onchange=()=>{try{localStorage.setItem('zhiji-chat-style',$('chat-style').value);}catch{}toast(({natural:'像平常一样聊',brief:'好，我会直接说重点',detailed:'好，我们慢慢展开看'})[$('chat-style').value]);};$('chat-scroll').onscroll=()=>{const el=$('chat-scroll');autoFollow=el.scrollHeight-el.scrollTop-el.clientHeight<140;$('jump-latest').hidden=autoFollow;};$('jump-latest').onclick=()=>scrollChat(true);$('chat-privacy').onclick=()=>openDialog('privacy-dialog');
function promptChat(text){view('chat');$('question').value=text;resizeComposer();$('question').focus();}
$('morning-chat').onclick=()=>promptChat('看看我的近期数据，今天最值得注意的一点是什么？像平时聊天那样告诉我就好。');document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>promptChat(b.dataset.prompt));

function removeImage(){image=null;$('image-preview').hidden=true;$('attached-image').removeAttribute('src');$('chat-image').value='';}$('remove-image').onclick=removeImage;
$('chat-image').onchange=async()=>{const file=$('chat-image').files[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('请选择 JPG、PNG 或 WebP 图片');if(file.size>20000000)throw new Error('图片过大，请选择小于 20 MB 的照片');const bitmap=await createImageBitmap(file),ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.82);if(data.length>5000000)throw new Error('压缩后图片仍过大，请裁剪后重试');image=data;$('attached-image').src=image;$('image-preview').hidden=false;set('chat-status','照片已准备好，仅在你发送问题时上传。');}catch(e){set('chat-status',e.message);removeImage();}};
function localDateTime(){const d=new Date();return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}$('note-time').value=localDateTime();
async function loadNotes(){const d=await request('journal');noteEntries=d.entries;$('entries').replaceChildren();for(const n of noteEntries){const card=document.createElement('article');card.className='card entry';const top=document.createElement('div');top.className='section-heading';const date=document.createElement('small');date.textContent=new Date(n.time).toLocaleString('zh-CN');const remove=document.createElement('button');remove.className='text-button';remove.textContent='删除';remove.onclick=async()=>{if(confirm('删除这条生活记录？'))try{await request('journal','DELETE',{id:n.id});await Promise.all([loadNotes(),loadCycles()]);}catch(e){set('note-status',e.message);}};top.append(date,remove);const text=document.createElement('p');text.textContent=n.text;const tags=document.createElement('div');tags.className='tags';tags.textContent=[({note:'日常',meal:'饮食',weight:'体重',mood:'心情',exercise:'运动',cycle:'生理周期',report:'健康报告'})[n.kind]||'日常',n.weight!=null?n.weight+' kg':'',n.mood!=null?'心情 '+n.mood+'/5':''].filter(Boolean).join(' · ');card.append(top,tags,text);if(n.nutrition){const macros=document.createElement('p');macros.className='meal-macros';macros.textContent=n.nutrition.kcal+' kcal · 蛋白质 '+n.nutrition.protein+'g · 碳水 '+n.nutrition.carbs+'g · 脂肪 '+n.nutrition.fat+'g';card.append(macros);}if(n.report){const summary=document.createElement('p');summary.className='muted';summary.textContent='已记录 '+n.report.coverage.mealCount+' 餐 · 运动 '+n.report.activity.workouts+' 次 · 体重 '+(n.report.weight.last??'未记录')+' kg';card.append(summary);} $('entries').append(card);}if(!noteEntries.length)set('entries','还没有生活记录。');set('journal-summary',new Set(noteEntries.map(n=>new Date(n.time).toLocaleDateString())).size+' 天的生活线索，慢慢连起来。');renderTimeline();window.HealthCare?.refresh();}
$('journal-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await request('journal','POST',{text:$('note').value,time:new Date($('note-time').value).toISOString(),kind:$('note-kind').value,weight:$('weight').value?Number($('weight').value):undefined,mood:$('mood').value?Number($('mood').value):undefined});$('note').value='';$('weight').value='';$('mood').value='';set('note-status','已加密保存到云端。');await loadNotes();}catch(e){set('note-status',e.message);}finally{button.disabled=false;}};$('export-journal').onclick=()=>download(noteEntries,'zhiji-journal.json');
let oldNotes=[];try{const n=JSON.parse(localStorage.getItem('zhiji-notes-v1')||'[]');if(Array.isArray(n))oldNotes=n;}catch{}$('local-import').hidden=!oldNotes.length;
$('import-notes').onclick=async()=>{$('import-notes').disabled=true;try{for(const n of oldNotes){const bytes=new TextEncoder().encode(String(n.time)+'|'+String(n.text));const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');await request('journal','POST',{id:digest,time:n.time,text:n.text,kind:'note'});}$('local-import').hidden=true;await loadNotes();set('note-status','旧记录已导入；本机原件仍保留。重复导入不会新增副本。');}catch(e){set('note-status',e.message);}finally{$('import-notes').disabled=false;}};
$('save-profile').onclick=async()=>{try{await request('profile','POST',{text:$('profile').value});set('profile-status','已保存；之后发送问题时会一起参考。');}catch(e){set('profile-status',e.message);}};
async function loadConnection(){const d=await request('oura/config');connected=d.connected;set('connection-badge',d.connected?'Oura 已连接':'等待 Oura 连接');set('connection-state',d.connected?'已授权。需要新增指标时，请先检查开发者应用权限，再补充授权。':d.configured?'已保存应用信息，请授权连接。':'请填写 Oura 开发者应用信息。');$('client-id').value=d.clientId||'';$('authorize').disabled=!d.configured;$('disconnect').hidden=!d.configured;$('sync').disabled=!d.connected;$('refresh-latest').disabled=!d.connected;if(!d.connected)syncLabel('先到“我的”连接 Oura');return d;}
$('config-form').onsubmit=async e=>{e.preventDefault();try{const secret=$('client-secret').value;$('client-secret').value='';await request('oura/config','POST',{clientId:$('client-id').value,clientSecret:secret});await loadConnection();set('oura-status','已保存，请重新授权。');}catch(e){set('oura-status',e.message);}};
$('authorize').onclick=async()=>{try{const d=await request('oura/start','POST',{});location.assign(d.url);}catch(e){set('oura-status',e.message);}};
$('disconnect').onclick=async()=>{if(confirm('删除本项目中的 Oura 应用信息、令牌和全部 Oura 数据？生活记录与聊天将保留。'))try{const d=await request('oura/disconnect','POST',{});alert(d.message);location.reload();}catch(e){set('oura-status',e.message);}};
let toastTimer;
function toast(text){set('toast',text);$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3200);}
function openDialog(id){const dialog=$(id);if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}
function closeDialog(id){const dialog=$(id);if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');}
function localDay(d=new Date()){const p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate());}
function prettyDay(day){const d=new Date(day+'T12:00:00');return Number.isFinite(d.getTime())?d.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}):day;}
function chooseDay(day){$('day').value=day;renderSnapshot();renderData();renderTimeline();}
function renderWeek(){const box=$('week-strip');box.replaceChildren();const anchor=new Date(($('day').value||localDay())+'T12:00:00'),known=new Set((state.data.daily_sleep||[]).map(dayOf));for(let i=6;i>=0;i--){const date=new Date(anchor);date.setDate(date.getDate()-i);const day=localDay(date),b=document.createElement('button');b.className='week-day'+(day===$('day').value?' active':'');const label=document.createElement('span');label.textContent=day===localDay()?'今天':date.toLocaleDateString('zh-CN',{weekday:'short'}).replace('周','');const num=document.createElement('b');num.textContent=date.getDate();const dot=document.createElement('i');dot.style.opacity=known.has(day)?'1':'0';b.setAttribute('aria-label',prettyDay(day));b.setAttribute('aria-pressed',String(day===$('day').value));b.append(label,num,dot);b.onclick=()=>chooseDay(day);box.append(b);}}
function renderRings(){const box=$('score-rings');box.replaceChildren();for(const [label,type,color] of [['睡眠','daily_sleep','#ae9bc9'],['恢复','daily_readiness','#e5a48a'],['活动','daily_activity','#9eae96']]){const score=sample(type)?.score,button=document.createElement('button');button.className='score-card';button.style.setProperty('--ring',color);const graphic=document.createElement('div');graphic.className='score-graphic';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 70 70');for(const name of ['track','progress']){const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('cx','35');c.setAttribute('cy','35');c.setAttribute('r','30');c.setAttribute('class',name);if(name==='progress')c.setAttribute('stroke-dasharray',score==null?'0 189':Math.max(0,Math.min(100,score))/100*189+' 189');svg.append(c);}const value=document.createElement('b');value.textContent=score??'—';graphic.append(svg,value);const copy=document.createElement('div');const title=document.createElement('strong');title.textContent=label;const date=document.createElement('small');date.textContent=score==null?'这天没有记录':$('day').value.slice(5).replace('-',' / ');copy.append(title,date);button.append(graphic,copy);button.onclick=()=>openMetric(label+'评分',type,'score','分');box.append(button);}}
function numericPoints(type,key){const map=new Map();for(const r of (state.data[type]||[]).slice().reverse()){if(typeof r[key]!=='number'||type==='sleep'&&r.type!=='long_sleep')continue;map.set(dayOf(r),{day:dayOf(r),value:r[key]});}return [...map.values()].sort((a,b)=>a.day.localeCompare(b.day));}
function miniSpark(type,key){const points=numericPoints(type,key).slice(-14);if(points.length<2)return null;let min=Infinity,max=-Infinity;for(const p of points){min=Math.min(min,p.value);max=Math.max(max,p.value);}const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 80 25');svg.setAttribute('class','mini-spark');svg.setAttribute('aria-hidden','true');const poly=document.createElementNS('http://www.w3.org/2000/svg','polyline');poly.setAttribute('points',points.map((p,i)=>(i/(points.length-1)*76+2)+','+(22-(p.value-min)/(max-min||1)*18)).join(' '));poly.setAttribute('fill','none');poly.setAttribute('stroke','var(--purple)');poly.setAttribute('stroke-width','1.5');poly.setAttribute('stroke-linecap','round');svg.append(poly);return svg;}
function renderHero(){const hour=new Date().getHours();set('greeting',hour<6?'夜深了，慢慢放下今天。':hour<12?'早上好，先听听身体的声音。':hour<18?'下午好，给自己一点空间。':'晚上好，今天辛苦了。');const sleep=sample('sleep'),score=sample('daily_readiness');set('hero-title',sleep?.total_sleep_duration!=null?'身体的故事，慢慢听。':'每一天，都更懂自己一点。');let text=sleep?.total_sleep_duration!=null?$('day').value.slice(5).replace('-','月')+'日这晚睡了 '+duration(sleep.total_sleep_duration)+'。':'你的数据和感受，都值得被认真对待。';if(score?.score!=null)text+=' 恢复评分 '+score.score+'，一起看看最近的变化。';set('hero-insight',text);}
function openMetric(label,type,key,unit){set('metric-title',label);set('metric-day',prettyDay($('day').value));const row=sample(type),value=row?.[key];$('metric-value').replaceChildren();const big=document.createElement('span');big.textContent=value==null?'—':durationFields.has(key)?duration(value):Math.round(value*100)/100;const small=document.createElement('small');small.textContent=value==null?'':unit;$('metric-value').append(big,small);const points=numericPoints(type,key).filter(p=>p.day<$('day').value).slice(-7);if(value!=null&&points.length){const avg=points.reduce((sum,p)=>sum+p.value,0)/points.length,delta=value-avg;set('metric-comparison','此前 '+points.length+' 个有效记录的均值：'+format(key,avg)+'。本次'+(delta>=0?'高':'低')+'了 '+format(key,Math.abs(delta))+'。这描述变化，不直接说明原因。');}else set('metric-comparison',value==null?'这一天还没有这个指标。换一天看看，或者先同步数据。':'还没有足够的历史记录来比较，先从今天开始了解自己。');const chartIndex=chartMetrics.findIndex(([,t,k])=>t===type&&k===key);$('metric-chart').replaceChildren();if(chartIndex>=0){$('trend-metric').value=chartIndex;chart();const svg=$('trend').querySelector('svg');if(svg)$('metric-chart').append(svg.cloneNode(true));}$('metric-detail').replaceChildren();if(row){const keys=type==='sleep'?['bedtime_start','bedtime_end','deep_sleep_duration','rem_sleep_duration','average_hrv','lowest_heart_rate']:['day','score','temperature_deviation','steps'];for(const k of keys){if(row[k]!=null)$('metric-detail').append(datum(fieldNames[k]||k,format(k,row[k])));}}$('metric-ask').onclick=()=>{closeDialog('metric-dialog');promptChat('我在看 '+$('day').value+' 的'+label+'（'+(value==null?'暂无记录':format(key,value))+'），和我平时比，这意味着什么？先简短说就好。');};openDialog('metric-dialog');}
function renderTimeline(){const box=$('today-timeline');box.replaceChildren();const day=$('day').value||localDay(),items=noteEntries.filter(n=>localDay(new Date(n.time))===day).slice(0,3);const sleep=sample('sleep');if(sleep?.bedtime_end){const line=document.createElement('div');line.className='timeline-line';const time=document.createElement('small');time.textContent=format('bedtime_end',sleep.bedtime_end)+' · Oura';const text=document.createElement('p');text.textContent='醒来了，这一晚睡了 '+duration(sleep.total_sleep_duration);line.append(time,text);box.append(line);}for(const n of items){const line=document.createElement('div');line.className='timeline-line';const time=document.createElement('small');time.textContent=new Date(n.time).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})+' · '+(({note:'日常',meal:'饮食',weight:'体重',mood:'心情',exercise:'运动',cycle:'生理周期',report:'健康报告'})[n.kind]||'日常');const text=document.createElement('p');text.textContent=n.text.length>100?n.text.slice(0,100)+'…':n.text;line.append(time,text);box.append(line);}if(!items.length&&!sleep){const p=document.createElement('p');p.className='muted';p.textContent='这一天还没有生活记录。几点睡、吃了什么、心里在想什么，都可以记一句。';box.append(p);}const mood=items.find(n=>n.kind==='mood'&&n.mood);document.querySelectorAll('[data-mood]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.mood)===mood?.mood));}
function setupExperience(){try{document.body.classList.toggle('dark',localStorage.getItem('zhiji-theme')==='dark');}catch{}$('theme-toggle').onclick=()=>{const dark=document.body.classList.toggle('dark');$('theme-toggle').textContent=dark?'☀':'☾';try{localStorage.setItem('zhiji-theme',dark?'dark':'light');}catch{}};$('go-today').onclick=()=>chooseDay(localDay());$('quick-food').onclick=()=>view('food');$('welcome-food').onclick=()=>$('chat-image').click();$('quick-weight').onclick=()=>{view('journal');$('note-kind').value='weight';$('weight').focus();$('note').placeholder='今天称重后的感受，也可以一起记下来。';};$('quick-talk').onclick=()=>promptChat('我想聊聊今天的心情，你先听我说。');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b.dataset.close));document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}}));document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const mood=Number(b.dataset.mood),labels={1:'很难受',2:'有点低落',3:'还好',4:'不错',5:'很好'};await request('journal','POST',{text:'今天的心情：'+labels[mood],kind:'mood',mood,time:new Date().toISOString()});set('mood-saved','已记下，谢谢你告诉我');await loadNotes();document.querySelectorAll('[data-mood]').forEach(x=>x.classList.toggle('selected',x===b));toast(mood<=2?'已记下。如果想说说，可以来找Health Care Agent。':'今天的心情，已经记下了。');}catch(e){toast(e.message);}finally{b.disabled=false;}});const viewport=window.visualViewport;const fit=()=>{document.documentElement.style.setProperty('--app-height',(viewport?.height||window.innerHeight)+'px');const keyboard=!!viewport&&window.innerHeight-viewport.height>160&&document.activeElement?.tagName==='TEXTAREA';document.body.classList.toggle('keyboard-open',keyboard);};viewport?.addEventListener('resize',fit);window.addEventListener('resize',fit);$('question').addEventListener('focus',()=>setTimeout(fit,100));$('question').addEventListener('blur',()=>setTimeout(fit,100));fit();}

function heartSamples(){return (state.data.heartrate||[]).filter(r=>Number.isFinite(r.bpm)&&r.bpm>0&&Number.isFinite(Date.parse(r.timestamp))&&Date.parse(r.timestamp)<=Date.now()+60000).slice().sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp));}
function newestStress(){return (state.data.daily_stress||[]).filter(r=>CycleModel.validDate(r.day)&&r.day<=localDay()).slice().sort((a,b)=>b.day.localeCompare(a.day))[0];}
function measurementTime(value){return new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function sampleAge(timestamp){const min=Math.max(0,Math.floor((Date.now()-Date.parse(timestamp))/60000));return min<1?'不到 1 分钟前':min<60?min+' 分钟前':min<1440?Math.floor(min/60)+' 小时前':Math.floor(min/1440)+' 天前';}
function heartPlot(container,rows,large=false){
 container.replaceChildren();if(rows.length<2){if(large)container.textContent='至少需要两个心率样本才能画趋势。';return;}
 const last=Date.parse(rows.at(-1).timestamp),points=rows.filter(r=>Date.parse(r.timestamp)>=last-6*3600000);if(points.length<2)return;
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',large?'0 0 400 150':'0 0 300 28');svg.setAttribute('role','img');svg.setAttribute('aria-label','最近一组心率样本；时间截至 '+measurementTime(last));
 const w=large?400:300,h=large?150:28,pad=large?20:3,start=Date.parse(points[0].timestamp),span=Math.max(1,last-start);let min=Infinity,max=-Infinity;for(const p of points){min=Math.min(min,p.bpm);max=Math.max(max,p.bpm);}const spread=Math.max(10,max-min);let path='',prev=0;
 for(const p of points){const t=Date.parse(p.timestamp),x=pad+(w-pad*2)*(t-start)/span,y=h-pad-(h-pad*2)*(p.bpm-min)/spread;path+=(prev&&t-prev<=1800000?' L':' M')+x.toFixed(1)+','+y.toFixed(1);prev=t;}
 const line=document.createElementNS(ns,'path');line.setAttribute('d',path);line.setAttribute('stroke','#ff375f');line.setAttribute('fill','none');line.setAttribute('stroke-width',large?'2.5':'2');line.setAttribute('stroke-linecap','round');svg.append(line);
 for(const p of points.filter((_,i)=>i===points.length-1||points.length<5)){const dot=document.createElementNS(ns,'circle');dot.setAttribute('cx',String(pad+(w-pad*2)*(Date.parse(p.timestamp)-start)/span));dot.setAttribute('cy',String(h-pad-(h-pad*2)*(p.bpm-min)/spread));dot.setAttribute('r',large?'3':'2');dot.setAttribute('fill','#ff375f');svg.append(dot);}
 if(large){svg.setAttribute('class','live-chart');for(const [x,value] of [[4,min],[4,max]]){const text=document.createElementNS(ns,'text');text.setAttribute('x',String(x));text.setAttribute('y',String(value===min?h-3:12));text.setAttribute('fill','currentColor');text.setAttribute('font-size','10');text.textContent=String(value);svg.append(text);}}container.append(svg);
}
function renderLatest(){
 const rows=heartSamples(),last=rows.at(-1);$('latest-bpm').replaceChildren();$('heart-mini-chart').replaceChildren();
 if(last){$('latest-bpm').append(document.createTextNode(String(last.bpm)+' '));const unit=document.createElement('small');unit.textContent='次/分';$('latest-bpm').append(unit);set('latest-heart-time','测量于 '+measurementTime(last.timestamp));const age=Date.now()-Date.parse(last.timestamp);set('heart-freshness',sampleAge(last.timestamp)+(age>1800000?' · 数据较旧':' · 最近样本')+' · 非实时');heartPlot($('heart-mini-chart'),rows);}
 else{set('latest-bpm','—');set('latest-heart-time','暂无云端心率样本');set('heart-freshness',statusFor('heartrate')?.status==='unauthorized'?'需要 Heartrate 授权':'先让 Oura App 完成同步');}
 const stress=newestStress();$('stress-meter').hidden=true;
 if(stress){set('latest-stress-value',stress.stress_high==null?'暂无时长':duration(stress.stress_high));set('latest-stress-time',stress.day+' · 高压力累计');if(Number.isFinite(stress.stress_high)&&Number.isFinite(stress.recovery_high)&&stress.stress_high+stress.recovery_high>0){$('stress-meter').hidden=false;$('stress-fill').style.width=(100*stress.stress_high/(stress.stress_high+stress.recovery_high))+'%';$('stress-meter').setAttribute('aria-label','高压力与高恢复累计时长的相对占比，不是实时压力分数');}}
 else{set('latest-stress-value','暂无汇总');set('latest-stress-time',statusFor('daily_stress')?.status==='unauthorized'?'需要补充授权':'等待 Oura 云端更新');}
 set('today-heading',new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}));
}
function openLatest(type){
 const heart=type==='heartrate',rows=heartSamples(),last=rows.at(-1),stress=newestStress();
 set('metric-title',heart?'最近心率测量':'压力与恢复');set('metric-day',heart?(last?measurementTime(last.timestamp):'暂无测量'):(stress?.day||'暂无汇总'));
 set('metric-value',heart?(last?last.bpm+' 次/分':'—'):(stress?.stress_high!=null?duration(stress.stress_high):'—'));
 set('metric-comparison',heart?'最近上传的心率样本，不等同于静息心率。':'高压力累计时间 · Oura 每日汇总');$('metric-chart').replaceChildren();$('metric-detail').replaceChildren();
 if(heart){heartPlot($('metric-chart'),rows,true);if(last){$('metric-detail').append(datum('最新测量时间',measurementTime(last.timestamp)),datum('样本年龄',sampleAge(last.timestamp)),datum('测量场景',enumNames[last.source]||last.source||'Oura 样本'));const first=rows.find(r=>Date.parse(r.timestamp)>=Date.parse(last.timestamp)-6*3600000);if(first)$('metric-detail').append(datum('图表时间范围',measurementTime(first.timestamp)+' — '+measurementTime(last.timestamp)));}}
 else if(stress){fields($('metric-detail'),stress);const status=statusFor('daily_stress');if(status)$('metric-detail').append(datum('接口读取时间',measurementTime(status.updated_at)));}
 if(heart&&statusFor('heartrate')?.updated_at)$('metric-detail').append(datum('接口读取时间',measurementTime(statusFor('heartrate').updated_at)));
 const note=document.createElement('p');note.className='live-detail-note';note.textContent=heart?'App 打开时自动更新，停留期间每 2 分钟请求云端数据。网页无法直接读取戒指蓝牙，也不能触发戒指测量；数据取决于 Oura App 上传。':'Oura 公开接口提供每日压力和恢复汇总，没有开放 App 内的实时压力曲线。这里不会把昨日汇总当成当前压力。';$('metric-detail').append(note);
 $('metric-ask').onclick=()=>{closeDialog('metric-dialog');promptChat(heart?'帮我看看最新上传的心率，注意测量时间和场景，先直白说重点。':'结合最新的压力每日汇总和我的生活记录，先说一个值得注意的变化。请区分日期，不要当成此刻压力。');};openDialog('metric-dialog');
}
let cycleEntries=[],cycleMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);
const flowLabels={none:'无出血',spotting:'点滴',light:'少量',medium:'中等',heavy:'较多'};
const symptomLabels={cramps:'腹痛',headache:'头痛',bloating:'腹胀',breast_tenderness:'乳房胀痛',fatigue:'疲倦',low_mood:'情绪低落',appetite_change:'食欲变化',acne:'痘痘'};
async function loadCycles(){const d=await request('cycle');cycleEntries=d.entries;renderCycle();window.CycleSync?.update(d.oura);}
function renderCycle(){
 const summary=CycleModel.summary(cycleEntries,localDay());
 set('cycle-home-title',summary.day?'周期第 '+summary.day+' 天':'认识自己的节奏');set('cycle-home-detail',summary.last?'上次开始 '+summary.last+' · 点此记录今天':'记录经期、症状与身体变化');
 set('cycle-title',summary.day?'周期第 '+summary.day+' 天':'从一次记录开始');
 set('cycle-description',summary.next?(summary.next<localDay()?'上次日历估计为 '+summary.next+'，尚未记录新的开始日。':'下次开始日估计 '+summary.next+'，实际日期可能变化。'):summary.variable?'最近记录的周期长短波动较大，暂不显示预测。':summary.last?'上次开始于 '+summary.last+'。继续补录实际开始日，至少 3 次后再估计。':'记录实际的月经开始日、经量和症状。');
 const stats=$('cycle-stats');stats.replaceChildren();for(const [label,value] of [['上次开始',summary.last||'未记录'],['最近周期长度',summary.typical?summary.typical+' 天（中位数）':'记录不足']]){const item=document.createElement('div'),b=document.createElement('b'),small=document.createElement('small');b.textContent=value;small.textContent=label;item.append(b,small);stats.append(item);}
 set('cycle-month',cycleMonth.toLocaleDateString('zh-CN',{year:'numeric',month:'long'}));const calendar=$('cycle-calendar');calendar.replaceChildren();const year=cycleMonth.getFullYear(),month=cycleMonth.getMonth(),offset=(new Date(year,month,1).getDay()+6)%7,total=new Date(year,month+1,0).getDate();
 for(let i=0;i<offset;i++)calendar.append(document.createElement('span'));
 for(let day=1;day<=total;day++){const date=localDay(new Date(year,month,day)),row=cycleEntries.find(r=>r.cycle.date===date)?.cycle,button=document.createElement('button');button.type='button';button.textContent=String(day);button.disabled=date>localDay();button.classList.toggle('today',date===localDay());button.classList.toggle('logged',!!row);button.classList.toggle('bleeding',!!row&&row.flow!=='none');button.classList.toggle('predicted',summary.next===date&&!row);button.setAttribute('aria-label',date+(row?'，'+flowLabels[row.flow]+(row.start?'，开始日':''):'，未记录')+(summary.next===date?'，日历估计开始日':''));button.onclick=()=>openCycleEntry(date);calendar.append(button);}
 const history=$('cycle-history');history.replaceChildren();for(const entry of cycleEntries.slice(0,30)){const row=entry.cycle,button=document.createElement('button');button.className='cycle-history-row';const icon=document.createElement('span');icon.className='cycle-icon';icon.textContent=row.flow==='none'?'◌':'❋';const copy=document.createElement('span'),title=document.createElement('strong'),detail=document.createElement('small');title.textContent=row.date+' · '+flowLabels[row.flow]+(row.start?' · 开始日':'');detail.textContent=row.symptoms.map(v=>symptomLabels[v]).join('、')||row.note||'已记录';const arrow=document.createElement('b');arrow.textContent='›';copy.append(title,detail);button.append(icon,copy,arrow);button.onclick=()=>openCycleEntry(row.date);history.append(button);}if(!cycleEntries.length)history.textContent='还没有周期记录。可以先补录最近一次开始日。';
}
function fillCycleEntry(date){
 const row=cycleEntries.find(e=>e.cycle.date===date)?.cycle;$('cycle-start').checked=!!row?.start;$('cycle-note').value=row?.note||'';
 document.querySelectorAll('input[name="flow"]').forEach(el=>el.checked=el.value===(row?.flow||'none'));document.querySelectorAll('input[name="symptom"]').forEach(el=>el.checked=!!row?.symptoms.includes(el.value));$('delete-cycle').hidden=!row;set('cycle-save-status','');
}
function openCycleEntry(date=localDay()){$('cycle-date').value=date;$('cycle-date').max=localDay();fillCycleEntry(date);openDialog('cycle-entry-dialog');}
function setupCycleUI(){
 $('open-cycle').onclick=()=>view('cycle');$('log-cycle-today').onclick=()=>openCycleEntry();$('cycle-prev').onclick=()=>{cycleMonth=new Date(cycleMonth.getFullYear(),cycleMonth.getMonth()-1,1);renderCycle();};$('cycle-next').onclick=()=>{cycleMonth=new Date(cycleMonth.getFullYear(),cycleMonth.getMonth()+1,1);renderCycle();};$('cycle-date').onchange=()=>fillCycleEntry($('cycle-date').value);
 $('ask-cycle').onclick=()=>promptChat('结合我记录的生理周期、症状、睡眠和心率，最近有没有值得注意的变化？请先说重点，区分实际记录和推测。');$('export-cycle').onclick=()=>download(cycleEntries,'health-care-agent-cycle.json');
 $('latest-heart').onclick=()=>openLatest('heartrate');$('latest-stress').onclick=()=>openLatest('daily_stress');
 document.querySelectorAll('input[name="flow"]').forEach(el=>el.onchange=()=>{if(['none','spotting'].includes(el.value))$('cycle-start').checked=false;});
 $('cycle-form').onsubmit=async e=>{e.preventDefault();$('save-cycle').disabled=true;$('delete-cycle').disabled=true;try{
  const date=$('cycle-date').value,flow=document.querySelector('input[name="flow"]:checked')?.value;if(!CycleModel.validDate(date)||date>localDay())throw Error('请选择今天或更早的日期');
  if($('cycle-start').checked&&!['light','medium','heavy'].includes(flow))throw Error('开始日请选择少量、中等或较多经量');
  await request('cycle','POST',{date,flow,start:$('cycle-start').checked,symptoms:[...document.querySelectorAll('input[name="symptom"]:checked')].map(el=>el.value),note:$('cycle-note').value});await Promise.all([loadCycles(),loadNotes()]);closeDialog('cycle-entry-dialog');toast('已保存周期记录，聊天也能参考。');
 }catch(e){set('cycle-save-status',e.message);}finally{$('save-cycle').disabled=false;$('delete-cycle').disabled=false;}};
 $('delete-cycle').onclick=async()=>{if(!confirm('删除这一天的周期记录？'))return;$('delete-cycle').disabled=true;$('save-cycle').disabled=true;try{await request('cycle','DELETE',{date:$('cycle-date').value});await Promise.all([loadCycles(),loadNotes()]);closeDialog('cycle-entry-dialog');toast('已删除当天记录。');}catch(e){set('cycle-save-status',e.message);}finally{$('delete-cycle').disabled=false;$('save-cycle').disabled=false;}};
}

let foodImage=null,foodEstimate=null,foodId=null,foodEdited=false,foodAnalyzing=false,reportPeriod='week',reportData=null;
async function prepareFoodPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20000000)throw Error('请选择小于 20 MB 的 JPG、PNG 或 WebP 照片');const bitmap=await createImageBitmap(file),ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const result=canvas.toDataURL('image/jpeg',.82);if(result.length>5000000)throw Error('照片过大，请裁剪后再试');return result;}
function invalidateFood(){foodEstimate=null;foodId=null;$('food-result').hidden=true;}
async function analyzeFood(){if(foodAnalyzing)return;foodAnalyzing=true;$('analyze-food').disabled=true;$('food-description').disabled=true;$('food-photo').disabled=true;$('food-remove-photo').disabled=true;invalidateFood();set('food-status','正在估算食物、份量和营养……');try{const d=await request('nutrition','POST',{text:$('food-description').value,image:foodImage||undefined});foodEstimate=d;foodId=crypto.randomUUID();foodEdited=false;set('food-title',d.title);set('food-range','热量估计范围 '+d.nutrition.range.low+'–'+d.nutrition.range.high+' kcal');set('food-assumptions',d.nutrition.assumptions);for(const key of ['kcal','protein','carbs','fat'])$('food-'+key).value=d.nutrition[key];$('food-result').hidden=false;$('save-food').disabled=false;set('save-food','记入饮食与报告');set('food-status','已估算，检查份量后记入。');}catch(e){set('food-status',e.message);}finally{foodAnalyzing=false;$('analyze-food').disabled=false;$('food-description').disabled=false;$('food-photo').disabled=false;$('food-remove-photo').disabled=false;}}
function setupFoodUI(){
 $('food-time').value=localDateTime();$('food-description').oninput=invalidateFood;$('food-photo').onchange=async()=>{const file=$('food-photo').files[0];if(!file)return;try{invalidateFood();foodImage=null;$('food-preview').hidden=true;foodImage=await prepareFoodPhoto(file);$('food-preview').src=foodImage;$('food-preview').hidden=false;$('food-remove-photo').hidden=false;set('food-status','照片已准备好，也可以补充份量和做法。');}catch(e){set('food-status',e.message);}};
 $('food-remove-photo').onclick=()=>{foodImage=null;$('food-photo').value='';$('food-preview').hidden=true;$('food-preview').removeAttribute('src');$('food-remove-photo').hidden=true;invalidateFood();};$('analyze-food').onclick=analyzeFood;
 for(const key of ['kcal','protein','carbs','fat'])$('food-'+key).oninput=()=>{foodEdited=true;set('food-range','已手动调整，保存时使用下方数值。');};
 $('save-food').onclick=async()=>{if(!foodEstimate||!foodId)return;$('save-food').disabled=true;try{const nutrition={...foodEstimate.nutrition};for(const key of ['kcal','protein','carbs','fat']){const value=$('food-'+key).value;if(value===''||!Number.isFinite(Number(value))||Number(value)<0)throw Error('请检查营养数值');nutrition[key]=Number(value);}if(foodEdited){delete nutrition.range;nutrition.assumptions+='（数值经用户调整）';}await request('journal','POST',{id:foodId,kind:'meal',time:new Date($('food-time').value).toISOString(),text:foodEstimate.title+($('food-description').value?'：'+$('food-description').value:''),nutrition});set('food-status','已记入饮食，周报和月报会自动计入。');set('save-food','已保存');await loadNotes();toast('这顿饭已记录。');}catch(e){set('food-status',e.message);$('save-food').disabled=false;}};
 document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{reportPeriod=b.dataset.report;document.querySelectorAll('[data-report]').forEach(el=>el.classList.toggle('selected',el===b));loadReport().catch(e=>set('report-status',e.message));});$('report-export').onclick=()=>{if(reportData)download(reportData,'health-care-agent-'+reportPeriod+'-'+reportData.to+'.json');};$('report-save').onclick=async()=>{try{$('report-save').disabled=true;await request('reports?period='+reportPeriod+'&timeZone='+encodeURIComponent(Intl.DateTimeFormat().resolvedOptions().timeZone),'POST',{});await loadNotes();toast('报告已保存到生活记录。');}catch(e){set('report-status',e.message);}finally{$('report-save').disabled=false;}};$('report-ask').onclick=()=>promptChat(reportPeriod==='morning'?'根据最新睡眠数据，昨晚睡得怎么样，今天适合怎么安排？先说明睡眠记录日期。':'请给我一份最近'+(reportPeriod==='week'?7:30)+'天的结构化健康报告，分别说饮食营养、运动、体重趋势、睡眠和接下来值得尝试的一件事。缺少记录时明确说明。');
}
let reportRequest=0;
async function loadReport(){const version=++reportRequest,period=reportPeriod;set('report-status','正在汇总已记录的数据……');$('report-body').replaceChildren();reportData=null;$('report-save').disabled=true;$('report-export').disabled=true;const d=await request('reports?period='+period+'&timeZone='+encodeURIComponent(Intl.DateTimeFormat().resolvedOptions().timeZone));if(version!==reportRequest)return;reportData=d;set('report-status',d.from+' — '+d.to+' · '+d.timeZone);$('report-save').disabled=false;$('report-export').disabled=false;
 const box=$('report-body'),card=(title,rows,note)=>{const el=document.createElement('article');el.className='card report-card';const h=document.createElement('h2');h.textContent=title;el.append(h);for(const [label,value] of rows)el.append(datum(label,value));if(note){const p=document.createElement('p');p.className='muted';p.textContent=note;el.append(p);}box.append(el);},v=(x,unit='')=>x==null?'暂无记录':x+unit;
 card('睡眠与恢复',[['最近睡眠记录',d.sleep.latest?.day||'暂无记录'],['睡眠时长',d.sleep.latest?.seconds!=null?duration(d.sleep.latest.seconds):'暂无记录'],['睡眠评分',v(d.sleep.score,' 分')+(d.sleep.scoreDay?' · '+d.sleep.scoreDay:'')],['恢复评分',v(d.sleep.readiness?.score,' 分')+(d.sleep.readiness?.day?' · '+d.sleep.readiness.day:'')],['期间平均睡眠',v(d.sleep.averageHours,' 小时')]],'先看记录日期。尚未上传的新一晚睡眠，不会由旧数据代替。');
 if(period!=='morning'){const n=d.nutrition;card('饮食与营养',[['记录覆盖',d.coverage.mealCount+' 餐 / '+d.coverage.mealDays+' 天'],['已记录餐食总热量',v(n.totals.kcal,' kcal')],['蛋白质 / 碳水 / 脂肪',[v(n.totals.protein,'g'),v(n.totals.carbs,'g'),v(n.totals.fat,'g')].join(' / ')],['记录日平均热量',v(n.averagePerRecordedDay?.kcal,' kcal')]],n.notes+(n.unestimatedMeals?' 另有 '+n.unestimatedMeals+' 餐尚无营养估算。':''));card('运动与活动',[['Oura 运动次数',v(d.activity.workouts,' 次')],['记录运动时长',v(d.activity.workoutMinutes,' 分钟')],['有效日期平均步数',v(d.activity.averageSteps,' 步')],['有效活动日期',d.coverage.activityDays+' / '+d.coverage.days+' 天'],['手动运动记录',d.activity.manualExerciseLogs+' 条']],'运动记录与活动消耗可能重叠，不重复累加。');card('体重趋势',[['体重记录覆盖',d.coverage.weightDays+' 天'],['首次 / 最新',[v(d.weight.first,' kg'),v(d.weight.last,' kg')].join(' / ')],['记录间变化',v(d.weight.change,' kg')],['期间平均 / 前一等长期间',[v(d.weight.average,' kg'),v(d.weight.previousAverage,' kg')].join(' / ')]],'单次变化不等于脂肪变化，先看多次记录。');}
 if(d.recordsMayBeTruncated){const p=document.createElement('p');p.textContent='记录数量达到读取上限，这份报告可能不完整。';box.append(p);}
}

async function init(){setupExperience();setupCycleUI();setupFoodUI();setupAutoSync();const id=location.hash.slice(1);if(['overview','data','chat','journal','cycle','food','reports','settings','care'].includes(id))view(id);const results=await Promise.allSettled([loadConnection(),loadHealth(),loadChat(),loadNotes(),loadCycles(),request('profile').then(d=>$('profile').value=d.text||'')]);const failures=results.filter(r=>r.status==='rejected');if(failures.length)set('global-status',[...new Set(failures.map(r=>r.reason.message))].join('；'));autoReady=true;if(connected)syncHealth({automatic:true});}init();

window.HealthCareBridge={view,prompt:promptChat,selectDate:chooseDay,refreshCycle:loadCycles,openCycle:openCycleEntry,sync:options=>{if(busy)return Promise.reject(Error('请等待当前同步完成'));if(!connected)return Promise.reject(Error('请先连接 Oura'));return syncHealth(options);}};
